-- NEARS-4122 QA fixtures. Runs ONLY on the clone multi_food_db_qa4122 (invoke: mysql -u root multi_food_db_qa4122 < clone-fixtures.sql).
-- Abort-on-mismatch assertion: the scalar subquery returns 2 rows (-> ERROR 1242, mysql stops) unless the DB is the clone.
SELECT IF(DATABASE() = 'multi_food_db_qa4122', 'DB_OK', (SELECT 1 UNION SELECT 2)) AS assert_db;

SELECT 'before' AS phase, (SELECT COUNT(*) FROM orders) AS orders_n, (SELECT COUNT(*) FROM parcel_cancellations) AS parcel_cancellations_n;

